import { object, string } from "yup";

import "./Registration.css";
import { Link } from "react-router-dom";
import ROUTES from "../../Routes";

const Registration = () => {
  const initialValues = {
    image: "",
    fisrt: "",
    last: "",
    maid: "",
    age: "",
    gender: "",
    email: "",
    phone: "",
    bisthdate: "",
  };

  const validationSchema = object({
    image: string(),
    fisrt: string(),
    last: string(),
    maid: string(),
    age: string(),
    gender: string(),
    email: string(),
    phone: string(),
    bisthdate: string(),
  });

