    <div className="mainReg">
      <Formik initialValues={initialValues} validationSchema={validationSchema} onSubmit={(e)=>addUser(e)}>
        <Form className="form">
          <Field className='field' name="fisrt" placeholder="Firstname"></Field>
          <Field className='field' name="last" placeholder="Lastname"></Field>
          <Field className='field' name="maid" placeholder="Maidenname"></Field>
          <Field className='field' name="image" placeholder="Image url"></Field>
          <Field className='field' name="age" placeholder="Age"></Field>
          <Field className='field' name="gender" placeholder="Gender"></Field>
          <Field className='field' name="email" placeholder="Email" type="email"></Field>
          <Field className='field' name="phone" placeholder="Phone number"></Field>
          <Field
            className='field' name="birthdate"
            placeholder="Birthdate (ex. 2000-1-1)"
          ></Field>
          <button className="submit">Submit</button>
        </Form>
      </Formik>
      <button className="back"><Link to={ROUTES.LOGIN}>Back</Link></button>
    </div>
  );
};

export default Registration;
